def enrich_annotations(original_annots):
    enriched = []
    for item in original_annots:
        old_html = item['t']
        match = re.search(r'>([^<]+)</span>', old_html)
        if not match:
            enriched.append(item)
            continue
            
        chord_full = match.group(1)
        chord_name = chord_full.split('/')[0] # ignore inversion for matching
        
        if "跳回" in chord_name or "Coda" in chord_name or "开头" in chord_name:
            enriched.append(item)
            continue

        ai_data = ai_knowledge.get(chord_name, {"func": "过渡和弦", "desc": "注意声部连接与触键。", "tag": "注意"})
        
        new_html = f"<div style='position:relative;display:inline-block;cursor:pointer;' onclick=\"const t=this.querySelector('.ai-tip');t.style.display=t.style.display==='none'?'block':'none';\">{old_html}<div class='ai-tip' style='display:none;position:absolute;bottom:120%;left:50%;transform:translateX(-50%);width:max-content;max-width:240px;background:#fff;border:1px solid #2e7d32;border-radius:8px;padding:12px;box-shadow:0 8px 24px rgba(0,0,0,0.15);z-index:9999;font-family:sans-serif;font-size:14px;color:#333;line-height:1.5;text-align:left;white-space:normal;'><div style='font-size:12px;color:#888;border-bottom:1px solid #eee;padding-bottom:4px;margin-bottom:6px;'>🤖 AI 乐理大师</div><div style='font-weight:bold;color:#2e7d32;margin-bottom:4px;font-size:15px;'>{ai_data['func']}</div><div style='margin-bottom:8px;font-size:13px;'>{ai_data['desc']}</div><div style='font-size:12px;background:#e8f5e9;color:#2e7d32;padding:2px 6px;border-radius:4px;display:inline-block;'>{ai_data['tag']}</div></div></div>"
        
        new_item = item.copy()
        new_item['t'] = new_html
        enriched.append(new_item)
        
    return enriched

new_annots = enrich_annotations(annots)
with open('enriched_annots.json', 'w') as f:
    json.dump(new_annots, f, ensure_ascii=False)
print(json.dumps(new_annots, ensure_ascii=False))